// Parse vision JSON, subtract container tare (from data/containers.json),
// then apply bias-table multiplier (learned). Merge with trigger payload.

// ── Static container lookup (mirror of data/containers.json — edit both
// places together, or refactor to fetch from Vercel in a future revision). ──
const CONTAINERS = {
  'banana-box-standard':      { tare_lbs: 3.2,  keywords: ['banana box','chiquita','dole','produce box'] },
  'milk-crate-standard':      { tare_lbs: 4.1,  keywords: ['milk crate','dairy crate'] },
  'bread-tray-plastic':       { tare_lbs: 2.8,  keywords: ['bread tray','bakery tray'] },
  '5gal-bucket-empty':        { tare_lbs: 2.2,  keywords: ['5 gallon bucket','five gallon','bucket'] },
  'pallet-wood-48x40':        { tare_lbs: 35.0, keywords: ['pallet','wooden pallet','gma pallet'] },
  'cardboard-box-small':      { tare_lbs: 0.8,  keywords: ['small cardboard box','small box'] },
  'cardboard-box-medium':     { tare_lbs: 1.6,  keywords: ['medium cardboard box','medium box'] },
  'cardboard-box-large':      { tare_lbs: 2.8,  keywords: ['large cardboard box','large box','shipping box'] },
  'reusable-shopping-bag':    { tare_lbs: 0.3,  keywords: ['reusable bag','shopping bag','grocery bag'] },
  'produce-mesh-bag-50lb':    { tare_lbs: 0.15, keywords: ['mesh bag','onion bag','potato bag'] },
  'no-container-loose':       { tare_lbs: 0.0,  keywords: ['loose','no container','bare','directly on floor'] }
};

function resolveContainer(visionResponse) {
  // Exact match on container_type key
  const key = (visionResponse.container_type || '').toLowerCase().trim();
  if (CONTAINERS[key]) return { key, ...CONTAINERS[key] };
  // Substring match across item_type + notes + container_type
  const haystack = [
    visionResponse.container_type || '',
    visionResponse.item_type || '',
    visionResponse.notes || ''
  ].join(' ').toLowerCase();
  for (const [k, def] of Object.entries(CONTAINERS)) {
    for (const kw of def.keywords) {
      if (haystack.includes(kw)) return { key: k, ...def };
    }
  }
  // Unmatched — no tare subtraction, log the raw classification
  return { key: visionResponse.container_type || 'unknown', tare_lbs: 0.0, unmatched: true };
}

// ── Parse vision JSON ──
// NIM (HTTP) returns choices[0].message.content; the older langchain node
// returned message.content / content. Accept all shapes.
let raw = $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.content ?? $json;
// Defensive: strip ```json fences if a model ever wraps its output.
if (typeof raw === 'string') {
  raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
}
let vision;
try {
  vision = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error('Vision returned non-JSON: ' + String(raw).slice(0, 300));
}

const trigger = $('Webhook: donation button').first().json.body || {};
const config = $('Load prompt + config').first().json;
const bridge = $('Build vision request').first().json || {};

// Bias table and learned densities — not wired in v1, default to empty.
// When Vercel serves /bias-table.json and /learned-densities.json, plug them
// in here via additional HTTP Request nodes + $('<name>').first().json.
const biasTable = {};
const densTable = {};

// ── Layer 1: container tare subtraction (deterministic) ──
const container = resolveContainer(vision);
// How many containers of this item are in the zone (v0.5 counting contract).
const containerCount = Number.isFinite(vision.container_count) && vision.container_count > 0
  ? Math.round(vision.container_count) : 1;
const totalTare = container.tare_lbs * containerCount;
const rawWeight = vision.weight_lbs;
const netWeight = (typeof rawWeight === 'number')
  ? Math.max(0, rawWeight - totalTare)
  : null;

// ── Layer 2: learned density override (if available for this item_type) ──
const densKey = (vision.item_type || '').toLowerCase().trim();
const dens = densTable[densKey];
let densityOverrideApplied = false;
let weightFromLearnedDensity = null;
if (dens && dens.using_learned && vision.estimated_volume_cu_in) {
  weightFromLearnedDensity = Math.max(0, vision.estimated_volume_cu_in * dens.density_lbs_per_cu_in_mean);
  densityOverrideApplied = true;
}

// ── Layer 3: bias multiplier from residual history ──
const biasKey = densKey;
const multiplier = (biasTable && biasTable[biasKey] && typeof biasTable[biasKey] === 'number') ? biasTable[biasKey] : 1.0;
const preBiasWeight = weightFromLearnedDensity !== null ? weightFromLearnedDensity : netWeight;
const adjustedWeight = (preBiasWeight !== null) ? preBiasWeight * multiplier : null;

// ── Ground truth from scale OCR (deterministic, passes through to Sheet) ──
const scaleReading = (typeof bridge.scale_reading_lbs === 'number' && bridge.scale_stable === true)
  ? bridge.scale_reading_lbs : null;
const residualVsScale = (scaleReading !== null && adjustedWeight !== null)
  ? adjustedWeight - scaleReading : null;

const IMPLAUSIBLE_LBS = 2000;
const implausible = typeof adjustedWeight === 'number' && adjustedWeight > IMPLAUSIBLE_LBS;
const vFlags = Array.isArray(vision.known_failure_flags) ? vision.known_failure_flags.slice() : [];
if (implausible) vFlags.push('implausible_weight_review');

return [{ json: {
  ...vision,
  donation_id: trigger.donation_id || (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now())),
  container_type: container.key,
  tare_lbs: totalTare,
  tare_lbs_each: container.tare_lbs,
  container_count: containerCount,
  container_fill_fraction: vision.container_fill_fraction ?? null,
  container_unmatched: container.unmatched === true,
  weight_lbs_raw: rawWeight,
  weight_lbs_net: netWeight,
  weight_lbs_from_learned_density: weightFromLearnedDensity,
  weight_lbs: adjustedWeight,
  density_override_applied: densityOverrideApplied,
  density_used: dens ? dens.density_lbs_per_cu_in_mean : null,
  density_source: dens && dens.using_learned ? 'learned' : 'model',
  known_failure_flags: vFlags,
  implausible_weight: implausible,
  confidence: implausible ? Math.min(vision.confidence ?? 0.5, 0.3) : (vision.confidence ?? null),
  bias_multiplier: multiplier,
  bias_applied: multiplier !== 1.0,
  scale_reading_lbs: scaleReading,
  scale_confidence: bridge.scale_confidence ?? null,
  true_weight_lbs: scaleReading,
  ground_truth_source: scaleReading !== null ? 'scale_ocr' : null,
  residual_vs_scale_lbs: residualVsScale,
  description: trigger.description ?? null,
  location: trigger.location ?? null,
  triggered_at: trigger.triggered_at ?? new Date().toISOString(),
  image_url: trigger.image_url ?? null,
  image_sha256: trigger.image_sha256 ?? null,
  image_bytes: trigger.image_bytes ?? null,
  archive_error: trigger.archive_error ?? null,
  prompt_version: config.prompt_version,
  model: config.model
}}];

// Zone-miss or null-weight: respond without writing to Farmbrite.
const v = $json;
return [{ json: {
  weight_lbs: null,
  weight_residual_est: null,
  item_type: v.item_type ?? null,
  confidence: v.confidence ?? null,
  charuco_detected: v.charuco_detected ?? false,
  farmbrite_id: null,
  notes: v.notes ?? (v.inside_zone === false ? 'Outside the yellow zone — reposition and retry.' : 'Could not estimate weight.')
}}];

// Farmbrite not configured — pass the parsed vision through so the PWA
// still shows weight + item + confidence, but farmbrite_id stays null.
return [{ json: { __farmbrite_skipped: true } }];

// Unified response shape for the PWA.
const parsed = $('Parse vision + tare + bias').first().json;
const fb = $json;
const farmbriteSkipped = fb?.__farmbrite_skipped === true;
const farmbriteId = farmbriteSkipped ? null : (fb?.id ?? fb?.uuid ?? fb?._id ?? null);

const residualEst = (parsed.weight_lbs_high != null && parsed.weight_lbs_low != null)
  ? (parsed.weight_lbs_high - parsed.weight_lbs_low) / 2
  : null;

let notes = parsed.notes ?? null;
if (farmbriteSkipped) {
  notes = (notes ? notes + ' · ' : '') + 'Farmbrite pending (no API key yet); execution logged in n8n history.';
}

return [{ json: {
  weight_lbs: parsed.weight_lbs ?? null,
  weight_residual_est: residualEst,
  item_type: parsed.item_type ?? null,
  confidence: parsed.confidence ?? null,
  charuco_detected: parsed.charuco_detected ?? false,
  container_type: parsed.container_type ?? null,
  container_count: parsed.container_count ?? null,
  container_fill_fraction: parsed.container_fill_fraction ?? null,
  tare_lbs: parsed.tare_lbs ?? null,
  weight_lbs_low: parsed.weight_lbs_low ?? null,
  weight_lbs_high: parsed.weight_lbs_high ?? null,
  implausible_weight: parsed.implausible_weight ?? false,
  prompt_version: parsed.prompt_version ?? null,
  model: parsed.model ?? null,
  farmbrite_id: farmbriteId,
  farmbrite_pending: farmbriteSkipped,
  notes
}}];

